/// C-FFI dispatch descriptor for SunSpec model 134. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_134: StaticModelSpec = StaticModelSpec {
    id: 134,
    length: model_134_c_length,
    writable: true,
    visit_read: model_134_c_visit_read,
    visit_write: model_134_c_visit_write,
};

fn model_134_c_length(_repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model134).model_length()
}

/// # Safety
/// For `kind` 1 or 2, `adapter` must point to a live `Model134{Stateful,Callback}Adapter`,
/// valid for the duration of the call.
unsafe fn model_134_c_visit_read(
    kind: u8,
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model134;
    let adapter: Option<&dyn ReadAdapter> = match kind {
        1 => Some(unsafe { &*(adapter as *const Model134StatefulAdapter) } as &dyn ReadAdapter),
        2 => Some(unsafe { &*(adapter as *const Model134CallbackAdapter) } as &dyn ReadAdapter),
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_134_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_134_c_visit_write(
    kind: u8,
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model134;
    let adapter: Option<&mut dyn WriteAdapter> = match kind {
        1 => {
            Some(unsafe { &mut *(adapter as *mut Model134StatefulAdapter) } as &mut dyn WriteAdapter)
        }
        2 => {
            Some(unsafe { &mut *(adapter as *mut Model134CallbackAdapter) } as &mut dyn WriteAdapter)
        }
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}
